  { id: 'b497', word: 'packet', translation: '小包；郵包', category: 'Business', example: 'She received a packet containing the registration documents.', exampleTranslation: '她收到了一個包含註冊文件的小包裹。' },
  { id: 'b498', word: 'pact', translation: '協定；條約', category: 'Business', example: 'The two corporations signed a mutual cooperation pact.', exampleTranslation: '這兩家公司簽署了相互合作的協定。' },
  { id: 'b499', word: 'pad', translation: '襯墊；便箋本', category: 'Business', example: 'He wrote down the meeting minutes on a writing pad.', exampleTranslation: '他在便箋本上寫下了會議記錄。' },
  { id: 'b500', word: 'pain', translation: '痛苦；努力', category: 'Business', example: 'The company spared no pains to ensure client satisfaction.', exampleTranslation: '公司不遺餘力（努力／不畏痛苦）以確保客戶滿意。' }
